import java.sql.Connection;
  import java.sql.PreparedStatement;

  import sailpoint.object.ProvisioningPlan;
  import sailpoint.object.ProvisioningResult;
  import sailpoint.object.ProvisioningPlan.AccountRequest;
  import sailpoint.object.ProvisioningPlan.AttributeRequest;
  import sailpoint.tools.Util;

  ProvisioningResult result = new ProvisioningResult();

  try {

    log.error("plan in create account rule :"+plan.toXml());
    AccountRequest acctReq = plan.getAccountRequests().get(0);

    String empid = acctReq.getNativeIdentity();
    String firstname = (String) acctReq.getAttributeRequest("firstname").getValue();
    String lastname = (String) acctReq.getAttributeRequest("lastname").getValue();
    String status = (String) acctReq.getAttributeRequest("status").getValue();

    String groupNames = null;

    AttributeRequest groupAttr = acctReq.getAttributeRequest("group_names");

    if (groupAttr != null) {
      Object value = groupAttr.getValue();

      if (value instanceof java.util.List) {
        groupNames = Util.listToCsv((java.util.List) value);
      } else if (value != null) {
        groupNames = value.toString();
      }
    }

    PreparedStatement ps = connection.prepareStatement(
      "INSERT INTO employee (empid, firstname, lastname, status, group_names) VALUES (?, ?, ?, ?, ?)"
    );

    ps.setString(1, empid);
    ps.setString(2, firstname);
    ps.setString(3, lastname);
    ps.setString(4, status);
    ps.setString(5, groupNames);

    ps.executeUpdate();
    ps.close();

    result.setStatus(ProvisioningResult.STATUS_COMMITTED);

  } catch (Exception e) {

    log.error("Create Account Failed", e);

    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError(e);

  }

  return result;
